css:
/* ========================= */
/* CONFIGURACIÓN GENERAL Y FUENTES */
/* ========================= */
* {
    overflow: visible !important;
}

.pdf-container {
    font-family: 'Poppins', sans-serif;
    font-size: 10px;
    color: #444;
    line-height: 1.3;
    padding-top: 20px;
    width: 100%;
    overflow: visible !important;
}

/* ========================= */
/* BLOQUE DE INFORMACIÓN */
/* ========================= */
.info-table {
    width: 100%;
    border-collapse: separate;
    border-spacing: 0 10px;
    margin-bottom: 20px;
    table-layout: fixed;
    page-break-inside: avoid;
}

.info-table td {
    vertical-align: top;
    padding: 0 10px;
}

/* Lado Izquierdo: Cliente - COLOR NARANJA */
.client-section {
    background-color: #fdfdfd;
    padding: 10px;
    border-left: 3px solid #FF6B15;
}

/* Lado Derecho: Orden - SIN FRANJA */
.quote-details {
    background-color: #fdfdfd;
    padding: 10px;
    text-align: right;
}

.section-title {
    font-weight: 700;
    font-size: 11px;
    color: #222;
    text-transform: uppercase;
    display: block;
    margin-bottom: 5px;
    border-bottom: 1px solid #eee;
    padding-bottom: 3px;
}

.info-line {
    margin: 3px 0;
    font-size: 10px;
}

/* ESTILOS DE DIRECCIÓN */
.client-address {
    margin-top: 8px;
    padding: 5px;
    background: #fff;
    border: 1px solid #eee;
    border-radius: 4px;
}

.client-address strong {
    color: #FF6B15;
    font-size: 10px;
    display: block;
    margin-bottom: 3px;
}

.client-address .address-line {
    color: #555;
    font-size: 10px;
    line-height: 1.4;
    display: block;
}

/* ========================= */
/* TABLA DE PRODUCTOS */
/* ========================= */
.table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 10px;
    font-size: 10px;
    page-break-inside: auto;
}

.table thead {
    display: table-header-group;
}

.table tbody {
    display: table-row-group;
}

.table thead th {
    background-color: #FF6B15;
    color: #ffffff;
    font-weight: 600;
    padding: 6px 4px;
    text-transform: uppercase;
    font-size: 9px;
    border: none;
}

.table tbody tr {
    page-break-inside: avoid;
    page-break-after: auto;
}

.table tbody td {
    padding: 8px 4px;
    border-bottom: 1px solid #f0f0f0;
    vertical-align: top;
    color: #333;
}

/* Estilos de Items - IMÁGENES MÁS GRANDES */
.item-image-cell {
    padding: 8px;
}

.item-image {
    max-width: 80px;
    max-height: 80px;
    width: auto;
    height: auto;
    object-fit: contain;
    display: block;
    margin: 0 auto;
}

.item-title {
    display: block;
    color: #000;
    margin-bottom: 2px;
}

.item-code {
    font-size: 9px;
    color: #888;
}

.item-fiscal-code {
    font-size: 9px;
    color: #FF6B15;
    margin-top: 2px;
    font-weight: 600;
}

.item-description {
    font-size: 9px;
    color: #666;
    margin-top: 2px;
    font-style: italic;
}

/* ========================= */
/* SECCIÓN DE TOTALES (INDEPENDIENTE) */
/* ========================= */
.totals-section {
    width: 100%;
    margin-top: 15px;
    page-break-inside: avoid;
}

.totals-table {
    width: 45%;
    float: right;
    border-collapse: collapse;
}

.totals-table td {
    padding: 4px 8px;
    text-align: right;
}

.total-label {
    font-weight: 600;
    color: #666;
    font-size: 10px;
}

.total-value {
    font-weight: 400;
    color: #333;
    font-size: 10px;
    width: 100px;
}

/* Total Final Destacado - EN NEGRO */
.grand-total-row td {
    border-top: 2px solid #333;
    padding-top: 8px;
    margin-top: 4px;
}

.big-label {
    font-size: 12px;
    color: #000;
    font-weight: 700;
}

.big-value {
    font-size: 12px;
    color: #000;
    font-weight: 700;
}

/* Limpiar floats */
.clearfix:after {
    content: "";
    display: table;
    clear: both;
}

/* ========================= */
/* TÉRMINOS DE PAGO - ESTILO TABLA PRODUCTOS */
/* ========================= */
.payment-terms {
    clear: both;
    padding-top: 20px;
    page-break-inside: avoid;
}

.payment-terms-title {
    font-size: 11px;
    color: #222;
    font-weight: 700;
    margin: 0 0 10px 0;
    text-transform: uppercase;
}

.payment-table {
    margin-top: 0;
    page-break-inside: auto;
}

.payment-table thead {
    display: table-header-group;
}

.payment-table tbody {
    display: table-row-group;
}

.payment-table thead th {
    background-color: #FF6B15;
    color: #ffffff;
    font-weight: 600;
    padding: 6px 8px;
    text-transform: uppercase;
    font-size: 9px;
    border: none;
}

.payment-table tbody tr {
    page-break-inside: avoid;
    page-break-after: auto;
}

.payment-table tbody td {
    padding: 8px;
    border-bottom: 1px solid #f0f0f0;
    color: #333;
    font-size: 10px;
}

/* ========================= */
/* TÉRMINOS Y CONDICIONES - FORZAR VISIBLE */
/* ========================= */
.terms {
    margin-top: 20px;
    padding: 0;
    background: none;
    border: none;
    font-size: 9px;
    color: #666;
    width: 100%;
    max-width: 100%;
    overflow: visible !important;
    page-break-inside: auto;
    height: auto !important;
    max-height: none !important;
}

.terms-title {
    font-weight: 700;
    display: block;
    margin-bottom: 8px;
    color: #222;
    font-size: 11px;
    text-transform: uppercase;
}

.terms-content {
    text-align: justify;
    line-height: 1.5;
    color: #666;
    word-wrap: break-word;
    overflow-wrap: break-word;
    white-space: normal;
    overflow: visible !important;
    height: auto !important;
    max-height: none !important;
}

/* ========================= */
/* SECCIÓN DE FIRMAS */
/* ========================= */
.signature-section {
    margin-top: 40px;
    margin-bottom: 30px;
    display: table;
    width: 100%;
    page-break-inside: avoid;
}

.signature-box {
    display: table-cell;
    width: 45%;
    padding: 0 20px;
    vertical-align: bottom;
}

.signature-box-ceo {
    position: relative;
}

.ceo-signature-img {
    max-width: 220px;
    max-height: 90px;
    width: auto;
    height: auto;
    display: block;
    margin: 0 auto -5px auto;
    object-fit: contain;
}

.signature-line {
    border-top: 2px solid #333;
    margin-bottom: 8px;
    margin-top: 10px;
}

.signature-label {
    font-size: 10px;
    font-weight: 700;
    color: #333;
    text-align: center;
    margin-bottom: 3px;
}

.signature-info {
    font-size: 9px;
    color: #666;
    text-align: center;
    font-weight: 600;
}

.signature-date {
    font-size: 9px;
    color: #888;
    text-align: center;
    margin-top: 5px;
    font-style: italic;
}

.signature-role {
    font-size: 9px;
    color: #FF6B15;
    text-align: center;
    font-weight: 600;
    margin-top: 2px;
}

/* ========================= */
/* FOOTER */
/* ========================= */
.pdf-footer {
    margin-top: 30px;
    text-align: center;
    color: #999;
    font-size: 9px;
}

.divider {
    border: 0;
    border-top: 1px solid #eee;
    margin-bottom: 5px;
}

.text-right { text-align: right; }
.text-center { text-align: center; }
